const TARGETS=new Set(["quinled-dig2go","athom-c3-tubes","waveshare-s3-tubes-remote"]);
const LINE=/^WLEDTUBES_BOOT v=1 target=([a-z0-9-]+) source=([0-9a-f]{40}) release=([A-Za-z0-9._-]+) tubes=([1-9][0-9]*)$/;

// AI: below section was generated by an AI
function canonicalIdentities(text) {
	const identities=[];
	for(const line of String(text).split(/\r?\n/)) {
		const match=LINE.exec(line);
		if(!match||!TARGETS.has(match[1]))continue;
		identities.push({version:1,target:match[1],source:match[2],release:match[3],tubes:Number(match[4])});
	}
	return identities;
}

export function parseWledTubesBootLine(text) {
	const identities=canonicalIdentities(text);
	return identities.length===1?identities[0]:null;
}

function sameIdentity(left,right) {
	return left.version===right.version&&left.target===right.target&&left.source===right.source&&left.release===right.release&&left.tubes===right.tubes;
}

function samePortInfo(left,right) {
	return Number.isInteger(left?.usbVendorId)&&Number.isInteger(left?.usbProductId)&&left.usbVendorId===right?.usbVendorId&&left.usbProductId===right?.usbProductId;
}

function beforeDeadline(promise,deadline,label) {
	const remaining=Math.max(0,deadline-Date.now());
	if(!remaining)return Promise.reject(Object.assign(Error(`${label} timed out`),{name:"TimeoutError"}));
	let timer;
	return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Object.assign(Error(`${label} timed out`),{name:"TimeoutError"})),remaining);})]).finally(()=>clearTimeout(timer));
}

function appendBytes(captured,value,maxBytes) {
	const bytes=value instanceof Uint8Array?value:new Uint8Array(value||0),next=bytes.subarray(0,maxBytes-captured.length),joined=new Uint8Array(captured.length+next.length);
	joined.set(captured);joined.set(next,captured.length);return joined;
}

// Captures one bounded serial transcript without writing payload bytes.
async function capturePort({port,deadline,maxBytes,attempts,attemptLimit=attempts.remaining,delay}) {
	let opened=false,reader=null,captured=new Uint8Array(0),openError=null;
	try {
		let portAttempts=0;
		while(attempts.remaining>0&&portAttempts<attemptLimit&&Date.now()<deadline) {
			attempts.remaining--;
			portAttempts++;
			try {await beforeDeadline(port.open({baudRate:115200,bufferSize:8192}),deadline,"Serial open");opened=true;break;}
			catch(error){openError=error;if(error.name==="TimeoutError"||attempts.remaining===0)break;try{await beforeDeadline(delay(Math.min(250*(attempts.initial-attempts.remaining),1000)),deadline,"Serial retry");}catch(error){openError=error;break;}}
		}
		if(!opened||!port.readable)return {opened:false,captured,reason:openError?.message||"Serial unavailable"};
		reader=port.readable.getReader();
		while(captured.length<maxBytes&&Date.now()<deadline) {
			let item;
			try {item=await beforeDeadline(reader.read(),deadline,"Serial read");}
			catch(error){return {opened:true,captured,reason:error.message};}
			if(item.done)break;
			captured=appendBytes(captured,item.value,maxBytes);
		}
		return {opened:true,captured,reason:captured.length===maxBytes?"Serial capture limit reached":"Serial capture completed"};
	} finally {
		if(reader){try{await reader.cancel();}catch{}try{reader.releaseLock();}catch{}}
		if(opened){try{await port.close();}catch{}}
	}
}

function classifyCapture(captured,expected,port,reason) {
	const identities=canonicalIdentities(new TextDecoder().decode(captured));
	if(identities.length!==1)return {status:identities.length>1?"mismatch":"pending",observed:identities[0]||null,bytesCaptured:captured.length,reason:identities.length>1?"Boot capture contained multiple canonical identities":reason,port};
	return {status:sameIdentity(identities[0],expected)?"verified":"mismatch",observed:identities[0],bytesCaptured:captured.length,port};
}

// Preserves a reusable selected port; otherwise rebinds only one exact VID/PID candidate.
export async function verifyControllerBoot({port,expected,enumeratePorts=null,timeoutMs=20000,maxBytes=8192,maxOpenAttempts=8,delay=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds))}={}) {
	if(!port||!expected||!TARGETS.has(expected.target)||!Number.isSafeInteger(maxBytes)||maxBytes<1||maxBytes>8192)throw Error("Invalid boot verification binding");
	if(typeof port.open!=="function")return {status:"pending",observed:null,bytesCaptured:0,reason:"Serial port is unavailable",port};
	const deadline=Date.now()+Math.min(Math.max(timeoutMs,1),20000),initial=Math.min(Math.max(maxOpenAttempts,1),8),attempts={initial,remaining:initial};
	const original=await capturePort({port,deadline,maxBytes,attempts,attemptLimit:typeof enumeratePorts==="function"?1:initial,delay});
	if(original.opened)return classifyCapture(original.captured,expected,port,original.reason);
	if(typeof enumeratePorts!=="function")return {status:"pending",observed:null,bytesCaptured:0,reason:original.reason,port};
	const originalInfo=port.getInfo?.();let reason=original.reason;
	while(attempts.remaining>0&&Date.now()<deadline) {
		let available;
		try {available=await beforeDeadline(Promise.resolve(enumeratePorts()),deadline,"Serial enumeration");}
		catch(error){return {status:"pending",observed:null,bytesCaptured:0,reason:error.message,port};}
		const candidates=Array.from(available||[]).filter(candidate=>samePortInfo(originalInfo,candidate.getInfo?.()));
		if(candidates.length>1)return {status:"pending",observed:null,bytesCaptured:0,reason:"Multiple matching USB serial ports are present",port};
		if(candidates.length===1) {
			const candidate=candidates[0],capture=await capturePort({port:candidate,deadline,maxBytes,attempts,attemptLimit:1,delay});reason=capture.reason;
			if(capture.opened)return classifyCapture(capture.captured,expected,candidate,capture.reason);
		} else attempts.remaining--;
		if(attempts.remaining>0)try{await beforeDeadline(delay(250),deadline,"Serial discovery");}catch(error){reason=error.message;break;}
	}
	return {status:"pending",observed:null,bytesCaptured:0,reason:reason||"The original USB serial port has not returned",port};
}
